package android.graphics; public final class Rect { public int left,top,right,bottom;public void set(int l,int t,int r,int b){left=l;top=t;right=r;bottom=b;}public boolean isEmpty(){return left>=right||top>=bottom;}public int width(){return right-left;}public boolean intersect(int l,int t,int r,int b){if(left<r&&l<right&&top<b&&t<bottom){set(Math.max(l,left),Math.max(t,top),Math.min(r,right),Math.min(b,bottom));return true;}return false;} public String toShortString(){return left+","+top+","+right+","+bottom;}public int height(){return bottom-top;}}